package io.github.tahausama210.driftwatch.ingest;

import io.github.tahausama210.driftwatch.hosts.HostFacts;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.Instant;
import java.util.List;
import java.util.UUID;

/**
 * A scan report as submitted by an agent. Field constraints are checked by Bean Validation;
 * cross-field rules (unique check ids, timestamp order, clock skew) by {@link ScanReportValidator}.
 *
 * @param scanId generated by the agent before the first submission attempt; the idempotency key
 * @param host current host facts; the stored host is updated with them
 */
public record ScanReport(
        @NotNull UUID scanId,
        @NotNull @Size(max = 32) String agentVersion,
        @NotNull Instant startedAt,
        @NotNull Instant finishedAt,
        @NotNull @Valid HostFacts host,
        @NotNull @Size(min = 1, max = 500) List<@NotNull @Valid CheckResultReport> results) {}
